#include<bits/stdc++.h>
using namespace std;
int main(){
    int N;
    scanf("%d",&N);
    vector<int>par(N+1,0);
    vector<vector<int>>ch(N+1);
    for(int i=2;i<=N;i++){
        scanf("%d",&par[i]);
        ch[par[i]].push_back(i);
    }
    vector<int>leaves;
    function<void(int)>dfs=[&](int u){
        if(ch[u].empty()){leaves.push_back(u);return;}
        for(int c:ch[u])dfs(c);
    };
    dfs(1);
    int L=leaves.size();
    if(L<=2){
        // Treewidth ≤ 2, just put everything in one bag
        printf("1\n%d",N);
        for(int i=1;i<=N;i++)printf(" %d",i);
        printf("\n");
        return 0;
    }
    // For each internal node u, collect its leaf descendants in DFS order
    // These form a contiguous segment of the ring
    // We process bottom-up, creating chain of bags per node
    vector<vector<int>>bags;
    vector<pair<int,int>>edges;
    // Returns the bag id that contains u and par[u] (connector bag)
    function<int(int)>solve=[&](int u)->int{
        if(ch[u].empty()) return -1;
        vector<int>leafCh, intCh;
        vector<int>intBags;
        for(int c:ch[u]){
            if(ch[c].empty()) leafCh.push_back(c);
            else{
                int b=solve(c);
                intCh.push_back(c);
                intBags.push_back(b);
            }
        }
        int p=par[u];
        int prevBag=-1;
        // Create bags for consecutive leaf children pairs
        for(int i=0;i<(int)leafCh.size();i++){
            vector<int>bg;
            bg.push_back(u);
            if(p) bg.push_back(p);
            bg.push_back(leafCh[i]);
            if(i+1<(int)leafCh.size()) bg.push_back(leafCh[i+1]);
            int bid=bags.size();
            bags.push_back(bg);
            if(prevBag>=0) edges.push_back({prevBag,bid});
            prevBag=bid;
        }
        if(leafCh.empty()){
            vector<int>bg={u};
            if(p) bg.push_back(p);
            int bid=bags.size();
            bags.push_back(bg);
            prevBag=bid;
        }
        for(int b:intBags){
            edges.push_back({prevBag,b});
        }
        return prevBag;
    };
    solve(1);
    // Add ring edge bags: for consecutive leaves on ring
    // Already partially covered, but need first-last connection
    // This simple approach may not fully cover ring edges; let's output what we have
    printf("%d\n",(int)bags.size());
    for(auto&b:bags){
        printf("%d",(int)b.size());
        for(int x:b) printf(" %d",x);
        printf("\n");
    }
    for(auto&[a,b]:edges) printf("%d %d\n",a+1,b+1);
}
